// Safely parse the AI response into clean fields for the sheet, email, and webhook response.
const raw = $json.choices && $json.choices[0] && $json.choices[0].message ? $json.choices[0].message.content : '';
let parsed;
try {
  // Strip accidental markdown fences before parsing
  const cleaned = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { error: 'parse_failed', raw_output: String(raw).slice(0, 500) };
}

const input = $('Normalize Input').first().json;

if (parsed.error || !parsed.linkedin_post) {
  return [{ json: {
    success: false,
    error: parsed.error || 'missing_fields',
    raw_output: parsed.raw_output || String(raw).slice(0, 500),
    title: input.title,
    email: input.email
  } }];
}

const thread = Array.isArray(parsed.x_thread) ? parsed.x_thread.map(t => String(t)) : [String(parsed.x_thread || '')];

return [{ json: {
  success: true,
  title: input.title,
  email: input.email,
  created_at: new Date().toISOString().slice(0, 16).replace('T', ' '),
  voice_summary: parsed.voice_summary || '',
  linkedin_post: parsed.linkedin_post || '',
  x_thread: thread.join('\n\n---\n\n'),
  x_thread_count: thread.length,
  instagram_caption: parsed.instagram_caption || '',
  status: 'Ready for review'
} }];

